-- twow-repo#575 ship pair (OB-20, 21.11.2026; OB-00 go (a), Ae17 world-data hotfix with twin PR, OB-10 review (a) 816892ac):
-- two ship routes the bot travel graph never had. Their transports load (gameobject_template type 15, taxi path set), but
-- the graph holds no transport (type 3) link for them, so a bot never plans a trip on them:
--   181646 'Ship - Auberdine to Stormwind' (TaxiPath 294): Stormwind harbour <-> Auberdine;
--   176250 'Windrunner' (TaxiPath 323): Auberdine <-> Alah'Thalas (high-elf start).
-- Rows built like TravelNodeMap::generateTransportNodes (boat branch) + makeDockNode, offline (generated by
-- evidence/ws-30/schiffe-ds4/tools/gen-ships.pl): a stop node at each TaxiPathNode stop (delay > 0, the DBC literal), a
-- dock node on the pier deck (navmesh point closest to stop z + 4.88 within 20 yd, main component), the ride link between
-- the stops (type 3, object = GO entry, distance 0.1, extra 0.1 / speed 30 = 0.003333, the taxi points stop -> stop,
-- stored forwards), the dock hops stop <-> dock (type 3, object = GO entry, 2-point path, distance = 3D length, extra 0.1),
-- and the dock walk links (linkgen 05af54aa + cropUselessLinks replay, navmesh = test realm C incl. its 58 overlay tiles).
-- At Auberdine the path-294 stop hops to the existing dock 'Serenitys Shoredock' (11 yd away); no old row is changed.
-- Not in this file: 190550 Sparkwater Port <-> Revantusk Village (TaxiPath 296). The Sparkwater pier is not in the navmesh
-- (no walkable poly above z 3 within 60 yd of the stop), so a dock there would be an island; ids 1871-1874 stay reserved.
-- Ids are FIXED: new nodes 1864-1870. The 21 existing nodes the new links reach are addressed by their key (name, map_id,
-- x/y/z rounded to 0.1 yd; refs 1-21 below) and mapped to their ids in this database (base dump / live: 112 ... 1860).
-- Gate @shp_do (every playerbot table is named only inside a prepared statement or the table guard, so a fresh bootstrap
-- without the module tables is a no-op): the three tables exist AND each of the 21 old nodes exists exactly once by key
-- AND no node with an id in 1864-1870 exists AND no link or path row references an id in 1864-1870.
-- States (@shpmig575 = 'shpmig575 state=<s> nodes=<n> links=<l> paths=<p>', rows in the id range after the run):
--   applied   = gate held, rows inserted, end-state CHECK passed;
--   replay    = all 7 ids present with the expected keys -> no-op;
--   skipped   = anything else (only 1-2 of the tables, an old node missing or ambiguous, a foreign row in the id range) -> no-op;
--   bootstrap = tables absent -> no-op (db-init stage 40 re-creates them from the module dump, which carries the same rows:
--               modules/mod-playerbots/sql/world/classic/ai_playerbot_travel_nodes.sql, same PR).
-- The status is set with SELECT ... INTO, not returned: the core AutoUpdater runs each statement through
-- MySQLConnection::Execute, which never reads a result set, so a bare SELECT would break the next statement
-- ("Commands out of sync"). Operator: run the file and `SELECT @shpmig575;` in the same client session.
-- Apply only while mangosd is stopped (saveNodeStore rewrites all three tables from memory). Replay-safe (gate + INSERT
-- IGNORE). Needs 20261027010000 (#731, nodes 1856/1857/1860 are walk targets of the Alah'Thalas dock).
-- Row counts: nodes +7 (ids 1864-1870), links +52 (transport 12 + walk 40), path points +10746 (transport 72 + walk 10674).
-- End state on the train base 1864 / 6386 / 441012 (dump 2911b1c4): 1871 / 6438 / 451758.
-- Every new link has at least one end in 1864-1870 and the gate requires the range to be empty before, so the rollback by
-- id range removes exactly the rows of this file.
-- Live runbook (as #731):
--   1. 'skipped' does not abort the file. On live, `SELECT @shpmig575;` right after it must read
--      'shpmig575 state=applied nodes=7 links=52 paths=10746'; anything else stops the deploy until the cause is known.
--   2. The rollback by id range holds only while no saveNodeStore has rewritten the graph (it renumbers the nodes by
--      name). Before it, run this file again in a client session: `SELECT @shpmig575;` = 'state=replay' (the 7 new
--      keys still sit on 1864-1870) -> the range rollback below; any other state -> roll back by key instead (name,
--      map_id and rounded x/y/z of the 7 new nodes from the node rows below, then their links and path points).
-- Acceptance (OB-10 G-2, CLI-PATH): first test run with this graph counts [Travel]/TransportWait entries per ship entry
-- (181646, 176250) and the uses per new link, and reports bot deaths within 100 yd of the docks 1865/1868/1870 and
-- 'Serenitys Shoredock' per faction and level (G-1 faction gate: twow-repo#731).
-- Rollback (exact, mangosd stopped):
--   DELETE FROM `ai_playerbot_travelnode_path` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870;
--   DELETE FROM `ai_playerbot_travelnode_link` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870;
--   DELETE FROM `ai_playerbot_travelnode` WHERE `id` BETWEEN 1864 AND 1870;
--   (the ledger row stays; re-running this file afterwards applies it again)

SET @shp_tables := (SELECT COUNT(DISTINCT `TABLE_NAME`) FROM `information_schema`.`TABLES` WHERE `TABLE_SCHEMA` = DATABASE()
  AND `TABLE_NAME` IN ('ai_playerbot_travelnode', 'ai_playerbot_travelnode_link', 'ai_playerbot_travelnode_path'));
SET @shp_oldok := 0, @shp_idn := 0, @shp_idl := 0, @shp_idp := 0, @shp_keyn := 0, @shpmig575 := NULL;

-- Row data (temporary tables, created unconditionally). The name collation is pinned to the module tables'.
DROP TEMPORARY TABLE IF EXISTS `_shp575_node`;
