  `x` FLOAT NOT NULL, `y` FLOAT NOT NULL, `z` FLOAT NOT NULL,
  `kx` DECIMAL(10,1) NOT NULL, `ky` DECIMAL(10,1) NOT NULL, `kz` DECIMAL(10,1) NOT NULL, `hits` INT NOT NULL DEFAULT 0);
