-- File integrity (always, also on a fresh bootstrap): the temporary tables hold exactly the header counts.
DROP TEMPORARY TABLE IF EXISTS `_shp575_check`;
CREATE TEMPORARY TABLE `_shp575_check` (`ok` TINYINT(1) NOT NULL CHECK (`ok` = 1));
INSERT INTO `_shp575_check` (`ok`) SELECT
  (SELECT COUNT(*) FROM `_shp575_node` WHERE `is_new` = 1 AND `id` = `ref` AND `id` BETWEEN 1864 AND 1870) = 7
  AND (SELECT COUNT(*) FROM `_shp575_node` WHERE `is_new` = 0 AND `id` IS NULL AND `ref` BETWEEN 1 AND 21) = 21
  AND (SELECT COUNT(*) FROM `_shp575_link`) = 52
  AND (SELECT COUNT(*) FROM `_shp575_path`) = 10746;

-- G1 key hits for every row, then the ids of the old nodes found exactly once
SET @shp_sql := IF(@shp_tables = 3,
  'UPDATE `_shp575_node` w SET w.`hits` = (SELECT COUNT(*) FROM `ai_playerbot_travelnode` n WHERE n.`name` = w.`name` AND n.`map_id` = w.`map_id`
      AND ROUND(n.`x`, 1) = w.`kx` AND ROUND(n.`y`, 1) = w.`ky` AND ROUND(n.`z`, 1) = w.`kz`)', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_sql := IF(@shp_tables = 3,
  'UPDATE `_shp575_node` w JOIN `ai_playerbot_travelnode` n ON n.`name` = w.`name` AND n.`map_id` = w.`map_id`
      AND ROUND(n.`x`, 1) = w.`kx` AND ROUND(n.`y`, 1) = w.`ky` AND ROUND(n.`z`, 1) = w.`kz`
      SET w.`id` = n.`id` WHERE w.`is_new` = 0 AND w.`hits` = 1', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_oldok := (SELECT COUNT(*) FROM `_shp575_node` WHERE `is_new` = 0 AND `hits` = 1 AND `id` IS NOT NULL);
-- G2 the fixed id range is unused: no node, no link, no path row
SET @shp_sql := IF(@shp_tables = 3, 'SELECT COUNT(*) INTO @shp_idn FROM `ai_playerbot_travelnode` WHERE `id` BETWEEN 1864 AND 1870', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_sql := IF(@shp_tables = 3, 'SELECT COUNT(*) INTO @shp_idl FROM `ai_playerbot_travelnode_link` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_sql := IF(@shp_tables = 3, 'SELECT COUNT(*) INTO @shp_idp FROM `ai_playerbot_travelnode_path` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
-- G3 replay: the new ids with their expected keys
SET @shp_sql := IF(@shp_tables = 3,
  'SELECT COUNT(*) INTO @shp_keyn FROM `ai_playerbot_travelnode` n JOIN `_shp575_node` w ON w.`is_new` = 1 AND n.`id` = w.`id`
      AND n.`name` = w.`name` AND n.`map_id` = w.`map_id`
      AND ROUND(n.`x`, 1) = w.`kx` AND ROUND(n.`y`, 1) = w.`ky` AND ROUND(n.`z`, 1) = w.`kz`', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_do := (@shp_tables = 3 AND @shp_oldok = 21 AND @shp_idn = 0 AND @shp_idl = 0 AND @shp_idp = 0);
SET @shp_state := CASE WHEN @shp_tables = 0 THEN 'bootstrap' WHEN @shp_do THEN 'applied'
  WHEN @shp_idn = 7 AND @shp_keyn = 7 THEN 'replay' ELSE 'skipped' END;

-- I1 nodes (linked = 1), I2 links, I3 path points
SET @shp_sql := IF(@shp_do,
  'INSERT IGNORE INTO `ai_playerbot_travelnode` (`id`, `name`, `map_id`, `x`, `y`, `z`, `linked`)
   SELECT `id`, `name`, `map_id`, `x`, `y`, `z`, 1 FROM `_shp575_node` WHERE `is_new` = 1 ORDER BY `id`', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_sql := IF(@shp_do,
  'INSERT IGNORE INTO `ai_playerbot_travelnode_link` (`node_id`, `to_node_id`, `type`, `object`, `distance`, `swim_distance`,
     `extra_cost`, `calculated`, `max_creature_0`, `max_creature_1`, `max_creature_2`)
   SELECT a.`id`, b.`id`, l.`type`, l.`object`, l.`distance`, l.`swim_distance`, l.`extra_cost`, l.`calculated`, l.`mc0`, l.`mc1`, l.`mc2`
     FROM `_shp575_link` l JOIN `_shp575_node` a ON a.`ref` = l.`ra` JOIN `_shp575_node` b ON b.`ref` = l.`rb`', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
SET @shp_sql := IF(@shp_do,
  'INSERT IGNORE INTO `ai_playerbot_travelnode_path` (`node_id`, `to_node_id`, `nr`, `map_id`, `x`, `y`, `z`)
   SELECT a.`id`, b.`id`, p.`nr`, p.`map_id`, p.`x`, p.`y`, p.`z`
     FROM `_shp575_path` p JOIN `_shp575_node` a ON a.`ref` = p.`ra` JOIN `_shp575_node` b ON b.`ref` = p.`rb`', 'DO 0');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;

-- End state (gate held): exactly the header counts in the id range, every row of this file present.
SET @shp_sql := IF(@shp_do,
  'INSERT INTO `_shp575_check` (`ok`) SELECT
  (SELECT COUNT(*) FROM `ai_playerbot_travelnode` WHERE `id` BETWEEN 1864 AND 1870) = 7
  AND (SELECT COUNT(*) FROM `ai_playerbot_travelnode` n JOIN `_shp575_node` w ON w.`is_new` = 1 AND n.`id` = w.`id`
      AND n.`name` = w.`name` AND n.`map_id` = w.`map_id`
      AND ROUND(n.`x`, 1) = w.`kx` AND ROUND(n.`y`, 1) = w.`ky` AND ROUND(n.`z`, 1) = w.`kz`) = 7
  AND (SELECT COUNT(*) FROM `ai_playerbot_travelnode_link` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870) = 52
  AND (SELECT COUNT(*) FROM `_shp575_link` l JOIN `_shp575_node` a ON a.`ref` = l.`ra` JOIN `_shp575_node` b ON b.`ref` = l.`rb`
      JOIN `ai_playerbot_travelnode_link` t ON t.`node_id` = a.`id` AND t.`to_node_id` = b.`id` AND t.`type` = l.`type` AND t.`object` = l.`object`) = 52
  AND (SELECT COUNT(*) FROM `ai_playerbot_travelnode_path` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870) = 10746
  AND (SELECT COUNT(*) FROM `_shp575_path` p JOIN `_shp575_node` a ON a.`ref` = p.`ra` JOIN `_shp575_node` b ON b.`ref` = p.`rb`
      JOIN `ai_playerbot_travelnode_path` t ON t.`node_id` = a.`id` AND t.`to_node_id` = b.`id` AND t.`nr` = p.`nr`) = 10746',
  'INSERT INTO `_shp575_check` (`ok`) VALUES (1)');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;

-- Status (no result set, see header): SELECT @shpmig575;
SET @shp_sql := IF(@shp_tables = 3,
  'SELECT CONCAT(''shpmig575 state='', @shp_state,
      '' nodes='', (SELECT COUNT(*) FROM `ai_playerbot_travelnode` WHERE `id` BETWEEN 1864 AND 1870),
      '' links='', (SELECT COUNT(*) FROM `ai_playerbot_travelnode_link` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870),
      '' paths='', (SELECT COUNT(*) FROM `ai_playerbot_travelnode_path` WHERE `node_id` BETWEEN 1864 AND 1870 OR `to_node_id` BETWEEN 1864 AND 1870)) INTO @shpmig575',
  'SELECT CONCAT(''shpmig575 state='', @shp_state, '' nodes=0 links=0 paths=0'') INTO @shpmig575');
PREPARE shp_stmt FROM @shp_sql; EXECUTE shp_stmt; DEALLOCATE PREPARE shp_stmt;
DROP TEMPORARY TABLE IF EXISTS `_shp575_path`;
DROP TEMPORARY TABLE IF EXISTS `_shp575_link`;
DROP TEMPORARY TABLE IF EXISTS `_shp575_node`;
DROP TEMPORARY TABLE IF EXISTS `_shp575_check`;
